            dashmap::mapref::entry::Entry::Occupied(o) => o.get().clone(),
            dashmap::mapref::entry::Entry::Vacant(v) => {
                let (command_tx, command_rx) = mpsc::channel(256);
                let (event_tx, _) = broadcast::channel(256);
